    intro: { en: 'Find the part of your journey that needs clarity. Every matter begins with fit, evidence, and an honest view of what is actually possible.', ta: 'உங்கள் பயணத்தில் தெளிவு தேவைப்படும் பகுதியைக் கண்டறியுங்கள். ஒவ்வொரு விவகாரமும் பொருத்தம், ஆதாரம், மற்றும் உண்மையில் என்ன சாத்தியம் என்பதன் நேர்மையான பார்வையுடன் தொடங்குகிறது.', hi: 'अपनी यात्रा के उस हिस्से को खोजें जिसे स्पष्टता चाहिए। हर मामला उपयुक्तता, साक्ष्य, और वास्तव में क्या संभव है, इसके ईमानदार दृष्टिकोण से शुरू होता है।' },
    t1: { en: 'Refugee Claims', ta: 'அகதி கோரிக்கைகள்', hi: 'शरणार्थी दावे' },
    x1: { en: 'Refugee claims, admissibility hearings and protection submissions.', ta: 'அகதி கோரிக்கைகள், அனுமதிப்பு விசாரணைகள் மற்றும் பாதுகாப்பு சமர்ப்பிப்புகள்.', hi: 'शरणार्थी दावे, प्रवेशयोग्यता सुनवाई और सुरक्षा प्रस्तुतीकरण।' },
    f1: { en: 'Basis of claim · hearing · evidence', ta: 'கோரிக்கை அடிப்படை · விசாரணை · ஆதாரம்', hi: 'दावा आधार · सुनवाई · साक्ष्य' },
    t2: { en: 'Refusals & Appeals', ta: 'நிராகரிப்புகள் & மேல்முறையீடுகள்', hi: 'अस्वीकृतियाँ और अपील' },
    x2: { en: 'IAD matters, refused applications and strategic case review.', ta: 'IAD விவகாரங்கள், நிராகரிக்கப்பட்ட விண்ணப்பங்கள் மற்றும் மூலோபாய வழக்கு மதிப்பாய்வு.', hi: 'IAD मामले, अस्वीकृत आवेदन और रणनीतिक मामला समीक्षा।' },
    f2: { en: 'Deadlines · remedy · evidentiary record', ta: 'காலக்கெடு · தீர்வு · ஆதார பதிவு', hi: 'समय सीमा · उपचार · साक्ष्य रिकॉर्ड' },
    t3: { en: 'Humanitarian & Compassionate', ta: 'மனிதநேய & கருணை', hi: 'मानवीय और करुणामय' },
    x3: { en: 'Human-centred submissions grounded in establishment, hardship and the best interests of children.', ta: 'நிலைநிறுத்தல், துன்பம் மற்றும் குழந்தைகளின் சிறந்த நலன்களில் வேரூன்றிய மனிதநேய சமர்ப்பிப்புகள்.', hi: 'स्थापना, कष्ट और बच्चों के सर्वोत्तम हित में निहित मानव-केंद्रित प्रस्तुतीकरण।' },
    f3: { en: 'Establishment · hardship · child\u2019s interests', ta: 'நிலைநிறுத்தல் · துன்பம் · குழந்தையின் நலன்கள்', hi: 'स्थापना · कष्ट · बच्चे का हित' },
    t4: { en: 'Family Sponsorships', ta: 'குடும்ப ஸ்பான்சர்ஷிப்கள்', hi: 'परिवार प्रायोजन' },
