        r1b: { en: "If you're already here and working below your training, a bridging strategy can move you toward PR without leaving." },
        r1b2: { en: "Express Entry and provincial streams both credit Canadian experience — but only when the occupation coding and evidence are right." },
        r1key: { en: "In-Canada · upgrade status" },
        r2l: { en: "Provincial nomination from Canadian experience" },
        r2b: { en: "Several provinces reward healthcare work done inside Canada with lower thresholds and faster nomination." },
        r2b2: { en: "The regulator requirements still apply, so we plan the nomination around the licensing timeline you're already living." },
        r2key: { en: "In-Canada · experience streams" },
        r3l: { en: "Work permit changes & extensions" },
        r3b: { en: "Moving between employers, roles, or permit types is common — and each change is a fresh decision with its own risk." },
        r3b2: { en: "We keep your status continuous while you change roles, so a gap doesn't reset your plans." },
        r3key: { en: "In-Canada · status continuity" },
        r4l: { en: "Status for your spouse and children" },
        r4b: { en: "Your family's status has to keep pace with yours through every change." },
        r4b2: { en: "Spousal work rights and children's status are maintained alongside your own applications, not after them." },
